WITH filtered AS (SELECT id, device_code, reading_ts, humidity, pressure, status_bits, firmware, INITCAP(TRIM(firmware)) AS firmware_title FROM device_readings WHERE reading_ts > TO_TIMESTAMP('2025-09-01 06:00:00')) SELECT id, reading_ts, humidity, pressure, firmware, SUM(humidity) OVER (ORDER BY CAST(reading_ts AS BIGINT) RANGE BETWEEN 1800 PRECEDING AND CURRENT ROW) AS humidity_sum_30m, MIN(pressure) OVER w_part AS device_code_min_pressure, AVG(humidity) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS humidity_avg_2_prior FROM filtered WHERE firmware IN ('1.1.0', '1.0.3') WINDOW w_part AS (PARTITION BY device_code)
